async function handleSubmit() {
  if (!file) return;
  controllerRef.current?.abort();
  const controller = new AbortController();
  controllerRef.current = controller;
  setError(null);
  setIsLoading(true);
  try {
    const { contract_id, review_id } = await uploadContract(file, instructions, controller.signal);
    const result = await pollReview(review_id, controller.signal, (s) => setStatusText(STATUS_TEXT[s] || 'Processing...'));
    if (result.status === 'completed') {
      router.push(`/contract/${contract_id}`);
    } else {
      setError(result.failure_message);
