2. Parse with ReviewResponseSchema
3. Branch on result:
   - Loading (pending/reading/evaluating): show shimmer with status text, poll every 2s
   - Completed with fairness: show evaluation results (ScoreBadge, clauses, summary, call-to-action)
   - Completed with null fairness: show "not a contract" message using summary
   - Failed: show error using failure_message
   - 404: show "not found" message
4. Page refresh reloads from backend (no data loss)

```typescript
'use client';

import { useEffect, useState } from 'react';
import { useParams } from 'next/navigation';
import type { ReviewResponse, ReviewCompleted, ReviewClause, FairnessRating } from '../../evaluate-contract/types';
import { ReviewResponseSchema } from '../../evaluate-contract/types';
import { FAIRNESS_SECTION_ORDER } from '../../evaluate-contract/fairness-utils';
import ScoreBadge from './ScoreBadge';
import ClauseSection from './ClauseSection';
import Link from 'next/link';

const BACKEND_URL = process.env.NEXT_PUBLIC_BACKEND_URL || 'http://localhost:8000';
const POLL_INTERVAL = 2000;
```

Key rendering logic:
```typescript
// For completed with fairness — show results
function EvaluationResults({ result }: { result: ReviewCompleted }) {
  const grouped = groupByFairness(result.clauses);
  return (
    <article className={PAGE_CONTAINER}>
      <h1>Evaluation complete</h1>
      {result.overall_fairness && <ScoreBadge rating={result.overall_fairness} />}
      {result.summary && <p>{result.summary}</p>}
      {result.call_to_action && (
        <ul>
          {result.call_to_action.map((item, i) => <li key={i}>{item}</li>)}
        </ul>
      )}
      <div>{FAIRNESS_SECTION_ORDER.map(rating => (
        <ClauseSection key={rating} rating={rating} clauses={grouped[rating]} />
      ))}</div>
      <Link href="/evaluate-contract">Evaluate another contract</Link>
    </article>
  );
}

// For completed with null fairness — not a contract
function NotAContract({ summary }: { summary: string | null }) {
  return (
    <div className={PAGE_CONTAINER}>
      <h1>Not a contract</h1>
      <p>{summary || 'The uploaded document does not appear to be a contract.'}</p>
      <Link href="/evaluate-contract">Try another document</Link>
    </div>
  );
}

// For failed
function EvaluationFailed({ message }: { message: string }) {
  return (
    <div className={PAGE_CONTAINER}>
      <h1>Evaluation failed</h1>
      <p>{message}</p>
      <Link href="/evaluate-contract">Try again</Link>
    </div>
  );
}
```

Main component:
```typescript
export default function ContractPage() {
  const { id } = useParams<{ id: string }>();
  const [review, setReview] = useState<ReviewResponse | null>(null);
  const [loading, setLoading] = useState(true);
  const [notFound, setNotFound] = useState(false);

  useEffect(() => {
    let cancelled = false;
    const controller = new AbortController();

    async function fetchAndPoll() {
      try {
        while (!cancelled) {
          const res = await fetch(`${BACKEND_URL}/api/contracts/${id}/review`, { signal: controller.signal });
          if (res.status === 404) { setNotFound(true); setLoading(false); return; }
          const data = ReviewResponseSchema.parse(await res.json());
          setReview(data);
          if (data.status === 'completed' || data.status === 'failed') { setLoading(false); return; }
          await new Promise(r => setTimeout(r, POLL_INTERVAL));
        }
      } catch (e) {
        if (!cancelled) { setNotFound(true); setLoading(false); }
      }
    }

    fetchAndPoll();
    return () => { cancelled = true; controller.abort(); };
  }, [id]);

  if (loading) return <LoadingState />;
  if (notFound) return <NoEvaluation />;
  if (!review) return <NoEvaluation />;
  if (review.status === 'failed') return <EvaluationFailed message={review.failure_message} />;
  if (review.status === 'completed') {
    if (review.overall_fairness) return <EvaluationResults result={review} />;
    return <NotAContract summary={review.summary} />;
  }
  return <LoadingState />;
}
```

